def main():
    prepared=[]
    for patch in PATCHES:
        path=Path(patch['path'])
        if path.is_symlink(): raise RuntimeError('Unexpected symlink')
        original=path.read_bytes() if path.exists() else b''
        actual=hashlib.sha256(original).hexdigest() if path.exists() else None
        if actual == patch['after']:
            continue
        if actual != patch['before']:
            raise RuntimeError('Source hash changed: '+str(path))
        updated=original
        for start,stop,replacement in reversed(patch['edits']):
            updated=updated[:start]+replacement.encode('utf-8')+updated[stop:]
        if hashlib.sha256(updated).hexdigest()!=patch['after']:
            raise RuntimeError('Output hash mismatch: '+str(path))
        compile(updated,str(path),'exec')
        prepared.append((path,updated))
    for path,updated in prepared:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(updated)
        print('Patched:',path)
    Path('sportsdb-qa').mkdir(exist_ok=True)
    Path('sportsdb-qa/patch-hashes.json').write_text(json.dumps(
        [{k:v for k,v in p.items() if k!='edits'} for p in PATCHES],indent=2))

if __name__=='__main__':main()
